import java.util.TreeSet;

public class BruteForceRank {
    private final TreeSet<String> perms = new TreeSet<>();

    public long rank(String s) {
        perms.clear();
        permute(s.toCharArray(), 0);
        long r = 1;
        for (String p : perms) {
            if (p.equals(s)) return r;
            r++;
        }
        return -1;
    }

    private void permute(char[] a, int k) {
        if (k == a.length) { perms.add(new String(a)); return; }
        for (int i = k; i < a.length; i++) {
            swap(a, k, i);
            permute(a, k + 1);
            swap(a, k, i);
        }
    }

    private void swap(char[] a, int i, int j) { char t = a[i]; a[i] = a[j]; a[j] = t; }

    public static void main(String[] args) {
        System.out.println(new BruteForceRank().rank("acb"));
    }
}

