import java.math.BigInteger;

public class LexRank {
    public BigInteger rank(String s) {
        int n = s.length();
        BigInteger[] fact = new BigInteger[n + 1];
        fact[0] = BigInteger.ONE;
        for (int i = 1; i <= n; i++) fact[i] = fact[i - 1].multiply(BigInteger.valueOf(i));

        int[] freq = new int[256];
        for (int i = 0; i < n; i++) freq[s.charAt(i)]++;

        BigInteger rank = BigInteger.ZERO;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            long smaller = 0;
            for (int ch = 0; ch < c; ch++) smaller += freq[ch];

            BigInteger denom = BigInteger.ONE;
            for (int ch = 0; ch < 256; ch++) denom = denom.multiply(fact[freq[ch]]);

            // block = smaller * (n-1-i)! / Pi freq! : permutations diverging here and going smaller
            BigInteger block = BigInteger.valueOf(smaller)
                .multiply(fact[n - 1 - i])
                .divide(denom);
            rank = rank.add(block);

            freq[c]--;
        }
        return rank.add(BigInteger.ONE);
    }

    public static void main(String[] args) {
        System.out.println(new LexRank().rank("aba"));
        System.out.println(new LexRank().rank("string"));
    }
}
